+const questions = [
+  {
+    id: 'q1',
+    text: 'Which of these languages are often used for systems programming?',
+    helpText: 'Systems programming involves software that provides services to other software.',
+    options: [
+      { id: 'q1-o1', label: 'C', value: 'c' },
+      { id: 'q1-o2', label: 'Rust', value: 'rust' },
+      { id: 'q1-o3', label: 'C++', value: 'cpp' },
+      { id: 'q1-o4', label: 'Java', value: 'java' }
+    ]
+  },
+  {
+    id: 'q2',
+    text: 'Which of these are functional programming languages (or have strong functional features)?',
+    options: [
+      { id: 'q2-o1', label: 'Haskell', value: 'haskell' },
+      { id: 'q2-o2', label: 'Lisp', value: 'lisp' },
+      { id: 'q2-o3', label: 'Elixir', value: 'elixir' },
+      { id: 'q2-o4', label: 'Erlang', value: 'erlang' }
+    ]
+  },
+  {
+    id: 'q3',
+    text: 'Which of these languages were created before 2000?',
+    options: [
+      { id: 'q3-o1', label: 'Java', value: 'java' },
+      { id: 'q3-o2', label: 'Python', value: 'python' },
+      { id: 'q3-o3', label: 'JavaScript', value: 'javascript' },
+      { id: 'q3-o4', label: 'Go', value: 'go' }
+    ]
+  }
+];
+
+function CheckboxOption({ option, name, onChange }) {
+  return `
+    <div class="option-item">
+      <input 
+        type="checkbox" 
+        id="${option.id}" 
+        name="${name}" 
+        value="${option.value}"
+        onchange="${onChange}"
+      >
+      <label for="${option.id}">${option.label}</label>
+    </div>
+  `;
+}
+
+function Question({ question }) {
+  const helpId = question.helpText ? `${question.id}-help` : null;
+  const optionsHtml = question.options.map(opt => 
+    CheckboxOption({ option: opt, name: question.id, onChange: `handleCheck('${question.id}', '${opt.value}')` })
+  ).join('');
+
+  return `
+    <div class="form-field">
+      <fieldset ${helpId ? `aria-describedby="${helpId}"` : ''}>
+        <legend>${question.text}</legend>
+        ${helpId ? `<p id="${helpId}" class="help-text">${question.helpText}</p>` : ''}
+        <div class="options-group">
+          ${optionsHtml}
+        </div>
+      </fieldset>
+    </div>
+  `;
+}
+
+function Quiz() {
+  const questionsHtml = questions.map(q => Question({ question: q })).join('');
+  
+  return `
+    <form id="quiz-form" onsubmit="handleSubmit(event)">
+      ${questionsHtml}
+      <button type="submit" class="submit-btn">Submit Quiz</button>
+    </form>
+  `;
+}
+
+// State management
+const state = {
+  selections: {
+    q1: [],
+    q2: [],
+    q3: []
+  }
+};
+
+window.handleCheck = (questionId, value) => {
+  const currentSelections = state.selections[questionId];
+  const index = currentSelections.indexOf(value);
+  if (index > -1) {
+    currentSelections.splice(index, 1);
+  } else {
+    currentSelections.push(value);
+  }
+};
+
+window.handleSubmit = (event) => {
+  event.preventDefault();
+  const resultsContainer = document.getElementById('results');
+  resultsContainer.innerHTML = `
+    <div class="results" role="status">
+      <h2>Quiz Submitted!</h2>
+      <p>Thank you for participating. You selected ${state.selections.q1.length + state.selections.q2.length + state.selections.q3.length} total answers.</p>
+    </div>
+  `;
+  resultsContainer.scrollIntoView({ behavior: 'smooth' });
+};
+
+document.addEventListener('DOMContentLoaded', () => {
+  const root = document.getElementById('quiz-root');
+  root.innerHTML = Quiz();
+});
+
